-- Full place authoring, explicit admin access, and conflict detection.
create or replace function public.admin_studio_get_place(p_admin_token text,p_slug text)
returns jsonb language plpgsql security definer set search_path=public as $$
begin
 if not public._is_admin(p_admin_token) then raise exception 'Admin access required'; end if;
 return (select to_jsonb(p)-'partner_access_token'-'partner_id' from public.places p where slug=p_slug);
end;$$;
grant execute on function public.admin_studio_get_place(text,text) to anon,authenticated;
create or replace function public.admin_studio_apply_place(p_admin_token text,p_draft_id uuid,p_revision timestamptz,p_images text[])
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_document jsonb; v_revision timestamptz; v_place public.places; v_existing public.places; v_fields jsonb; v_id uuid; v_key text; v_old jsonb;
begin
 if not public._is_admin(p_admin_token) then raise exception 'Admin access required'; end if;
 select document,updated_at into v_document,v_revision from public.admin_content_drafts where id=p_draft_id for update;
 if v_document is null or v_revision is distinct from p_revision then raise exception 'Draft changed. Save and review again'; end if;
 if v_document->>'contentPurpose' not in ('place_profile','place_update') then raise exception 'Place draft required'; end if;
 if length(trim(coalesce(v_document->>'title',''))) = 0 then raise exception 'Place name required'; end if;
 v_fields=coalesce(v_document->'placeDetails','{}'::jsonb);
 v_id=coalesce((v_document->'sourcePlace'->>'id')::uuid,p_draft_id);
 select * into v_existing from public.places where id=v_id for update;
 if v_document->>'contentPurpose'='place_update' and v_existing.id is null then raise exception 'Source place no longer exists'; end if;
 if v_existing.id is not null then
   if v_document->>'contentPurpose'='place_profile' then raise exception 'Place already created. Reopen it before applying again'; end if;
   if v_existing.name is distinct from v_document->'sourcePlace'->>'name' or v_existing.country is distinct from v_document->>'country' then raise exception 'Place changed elsewhere. Reopen it before applying';end if;
   v_old=to_jsonb(v_existing);
   foreach v_key in array['slug','category','town','google_maps_link','latitude','longitude','cuisine','price_range','opening_hours','ambiance','description','recommended_dishes','menu_link','rating','website','phone_number','is_featured','number_of_rooms','amenities','room_type','activities','duration','age_range','parish','address','perfect_for','curator_note','meal_type','type','kitchen_hours','instagram_url','is_hidden','menus','completed','booking_link','parent_place_id','place_role','brand_name','booking_contact_email','hospitality_group','day_pass_available','day_pass_price','day_pass_includes','day_pass_hours','day_pass_link','day_pass_notes','day_pass_child_price','day_pass_child_age','bookings_email','opening_hours_struct','kitchen_hours_struct','accepts_stay_bookings','booking_mode','booking_contact_name','check_in_time','check_out_time','min_nights','max_guests','cancellation_policy_text','deposit_instructions','deposit_required','deposit_default_amount','deposit_currency','commission_terms','taxes_fees_notes','hold_expiry_minutes','internal_booking_notes','stay_booking_mode','stay_availability_source','stay_availability_url','stay_room_types','stay_min_nights','stay_max_guests','stay_commission_terms','insider_enabled','brand_color'] loop
    if v_old->v_key is distinct from v_document->'placeBaseline'->v_key then raise exception 'Place changed elsewhere. Reopen it before applying'; end if;
   end loop;
   if to_jsonb(coalesce(v_existing.image,'{}'::text[])) is distinct from v_document->'originalPlaceImages' then raise exception 'Place photos changed elsewhere. Reopen it before applying'; end if;
   v_place=v_existing;
 else
   v_place.id=v_id;v_place.is_featured=false;v_place.is_hidden=false;v_place.completed=false;v_place.day_pass_available=false;v_place.accepts_stay_bookings=false;v_place.booking_mode='request_only';v_place.stay_booking_mode='request_only';v_place.min_nights=1;v_place.hold_expiry_minutes=10;v_place.deposit_required=false;v_place.deposit_currency='USD';v_place.insider_enabled=false;
 end if;
 -- Only reviewed editable columns can enter the typed record. Credential and ownership fields are excluded.
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into v_fields from jsonb_each(v_fields) where key=any(array['slug','category','town','google_maps_link','latitude','longitude','cuisine','price_range','opening_hours','ambiance','description','recommended_dishes','menu_link','rating','website','phone_number','is_featured','number_of_rooms','amenities','room_type','activities','duration','age_range','parish','address','perfect_for','curator_note','meal_type','type','kitchen_hours','instagram_url','is_hidden','menus','completed','booking_link','parent_place_id','place_role','brand_name','booking_contact_email','hospitality_group','day_pass_available','day_pass_price','day_pass_includes','day_pass_hours','day_pass_link','day_pass_notes','day_pass_child_price','day_pass_child_age','bookings_email','opening_hours_struct','kitchen_hours_struct','accepts_stay_bookings','booking_mode','booking_contact_name','check_in_time','check_out_time','min_nights','max_guests','cancellation_policy_text','deposit_instructions','deposit_required','deposit_default_amount','deposit_currency','commission_terms','taxes_fees_notes','hold_expiry_minutes','internal_booking_notes','stay_booking_mode','stay_availability_source','stay_availability_url','stay_room_types','stay_min_nights','stay_max_guests','stay_commission_terms','insider_enabled','brand_color']);
 v_place=jsonb_populate_record(v_place,v_fields);
 v_place.name=v_document->>'title';v_place.country=v_document->>'country';v_place.image=p_images;
 if coalesce(v_place.slug,'')='' then v_place.slug=trim(both '-' from regexp_replace(lower(v_place.name),'[^a-z0-9]+','-','g'))||'-'||left(v_id::text,8);end if;
 if v_place.category not in ('eat','stay','play') or v_place.category is null then raise exception 'Category must be eat, stay or play';end if;
 if v_place.latitude not between -90 and 90 or v_place.longitude not between -180 and 180 then raise exception 'Invalid coordinates';end if;
 if v_existing.id is null then
  insert into public.places(id,name,country,image,"slug", "category", "town", "google_maps_link", "latitude", "longitude", "cuisine", "price_range", "opening_hours", "ambiance", "description", "recommended_dishes", "menu_link", "rating", "website", "phone_number", "is_featured", "number_of_rooms", "amenities", "room_type", "activities", "duration", "age_range", "parish", "address", "perfect_for", "curator_note", "meal_type", "type", "kitchen_hours", "instagram_url", "is_hidden", "menus", "completed", "booking_link", "parent_place_id", "place_role", "brand_name", "booking_contact_email", "hospitality_group", "day_pass_available", "day_pass_price", "day_pass_includes", "day_pass_hours", "day_pass_link", "day_pass_notes", "day_pass_child_price", "day_pass_child_age", "bookings_email", "opening_hours_struct", "kitchen_hours_struct", "accepts_stay_bookings", "booking_mode", "booking_contact_name", "check_in_time", "check_out_time", "min_nights", "max_guests", "cancellation_policy_text", "deposit_instructions", "deposit_required", "deposit_default_amount", "deposit_currency", "commission_terms", "taxes_fees_notes", "hold_expiry_minutes", "internal_booking_notes", "stay_booking_mode", "stay_availability_source", "stay_availability_url", "stay_room_types", "stay_min_nights", "stay_max_guests", "stay_commission_terms", "insider_enabled", "brand_color") values(v_id,v_place.name,v_place.country,p_images,(v_place)."slug", (v_place)."category", (v_place)."town", (v_place)."google_maps_link", (v_place)."latitude", (v_place)."longitude", (v_place)."cuisine", (v_place)."price_range", (v_place)."opening_hours", (v_place)."ambiance", (v_place)."description", (v_place)."recommended_dishes", (v_place)."menu_link", (v_place)."rating", (v_place)."website", (v_place)."phone_number", (v_place)."is_featured", (v_place)."number_of_rooms", (v_place)."amenities", (v_place)."room_type", (v_place)."activities", (v_place)."duration", (v_place)."age_range", (v_place)."parish", (v_place)."address", (v_place)."perfect_for", (v_place)."curator_note", (v_place)."meal_type", (v_place)."type", (v_place)."kitchen_hours", (v_place)."instagram_url", (v_place)."is_hidden", (v_place)."menus", (v_place)."completed", (v_place)."booking_link", (v_place)."parent_place_id", (v_place)."place_role", (v_place)."brand_name", (v_place)."booking_contact_email", (v_place)."hospitality_group", (v_place)."day_pass_available", (v_place)."day_pass_price", (v_place)."day_pass_includes", (v_place)."day_pass_hours", (v_place)."day_pass_link", (v_place)."day_pass_notes", (v_place)."day_pass_child_price", (v_place)."day_pass_child_age", (v_place)."bookings_email", (v_place)."opening_hours_struct", (v_place)."kitchen_hours_struct", (v_place)."accepts_stay_bookings", (v_place)."booking_mode", (v_place)."booking_contact_name", (v_place)."check_in_time", (v_place)."check_out_time", (v_place)."min_nights", (v_place)."max_guests", (v_place)."cancellation_policy_text", (v_place)."deposit_instructions", (v_place)."deposit_required", (v_place)."deposit_default_amount", (v_place)."deposit_currency", (v_place)."commission_terms", (v_place)."taxes_fees_notes", (v_place)."hold_expiry_minutes", (v_place)."internal_booking_notes", (v_place)."stay_booking_mode", (v_place)."stay_availability_source", (v_place)."stay_availability_url", (v_place)."stay_room_types", (v_place)."stay_min_nights", (v_place)."stay_max_guests", (v_place)."stay_commission_terms", (v_place)."insider_enabled", (v_place)."brand_color");
 else
  update public.places set name=v_place.name,country=v_place.country,image=p_images,"slug" = (v_place)."slug", "category" = (v_place)."category", "town" = (v_place)."town", "google_maps_link" = (v_place)."google_maps_link", "latitude" = (v_place)."latitude", "longitude" = (v_place)."longitude", "cuisine" = (v_place)."cuisine", "price_range" = (v_place)."price_range", "opening_hours" = (v_place)."opening_hours", "ambiance" = (v_place)."ambiance", "description" = (v_place)."description", "recommended_dishes" = (v_place)."recommended_dishes", "menu_link" = (v_place)."menu_link", "rating" = (v_place)."rating", "website" = (v_place)."website", "phone_number" = (v_place)."phone_number", "is_featured" = (v_place)."is_featured", "number_of_rooms" = (v_place)."number_of_rooms", "amenities" = (v_place)."amenities", "room_type" = (v_place)."room_type", "activities" = (v_place)."activities", "duration" = (v_place)."duration", "age_range" = (v_place)."age_range", "parish" = (v_place)."parish", "address" = (v_place)."address", "perfect_for" = (v_place)."perfect_for", "curator_note" = (v_place)."curator_note", "meal_type" = (v_place)."meal_type", "type" = (v_place)."type", "kitchen_hours" = (v_place)."kitchen_hours", "instagram_url" = (v_place)."instagram_url", "is_hidden" = (v_place)."is_hidden", "menus" = (v_place)."menus", "completed" = (v_place)."completed", "booking_link" = (v_place)."booking_link", "parent_place_id" = (v_place)."parent_place_id", "place_role" = (v_place)."place_role", "brand_name" = (v_place)."brand_name", "booking_contact_email" = (v_place)."booking_contact_email", "hospitality_group" = (v_place)."hospitality_group", "day_pass_available" = (v_place)."day_pass_available", "day_pass_price" = (v_place)."day_pass_price", "day_pass_includes" = (v_place)."day_pass_includes", "day_pass_hours" = (v_place)."day_pass_hours", "day_pass_link" = (v_place)."day_pass_link", "day_pass_notes" = (v_place)."day_pass_notes", "day_pass_child_price" = (v_place)."day_pass_child_price", "day_pass_child_age" = (v_place)."day_pass_child_age", "bookings_email" = (v_place)."bookings_email", "opening_hours_struct" = (v_place)."opening_hours_struct", "kitchen_hours_struct" = (v_place)."kitchen_hours_struct", "accepts_stay_bookings" = (v_place)."accepts_stay_bookings", "booking_mode" = (v_place)."booking_mode", "booking_contact_name" = (v_place)."booking_contact_name", "check_in_time" = (v_place)."check_in_time", "check_out_time" = (v_place)."check_out_time", "min_nights" = (v_place)."min_nights", "max_guests" = (v_place)."max_guests", "cancellation_policy_text" = (v_place)."cancellation_policy_text", "deposit_instructions" = (v_place)."deposit_instructions", "deposit_required" = (v_place)."deposit_required", "deposit_default_amount" = (v_place)."deposit_default_amount", "deposit_currency" = (v_place)."deposit_currency", "commission_terms" = (v_place)."commission_terms", "taxes_fees_notes" = (v_place)."taxes_fees_notes", "hold_expiry_minutes" = (v_place)."hold_expiry_minutes", "internal_booking_notes" = (v_place)."internal_booking_notes", "stay_booking_mode" = (v_place)."stay_booking_mode", "stay_availability_source" = (v_place)."stay_availability_source", "stay_availability_url" = (v_place)."stay_availability_url", "stay_room_types" = (v_place)."stay_room_types", "stay_min_nights" = (v_place)."stay_min_nights", "stay_max_guests" = (v_place)."stay_max_guests", "stay_commission_terms" = (v_place)."stay_commission_terms", "insider_enabled" = (v_place)."insider_enabled", "brand_color" = (v_place)."brand_color" where id=v_id;
 end if;
 return jsonb_build_object('sourcePlace',jsonb_build_object('id',v_id,'slug',v_place.slug,'name',v_place.name),'baseline',(select jsonb_object_agg(key,value) from jsonb_each(to_jsonb(v_place)) where key=any(array['slug','category','town','google_maps_link','latitude','longitude','cuisine','price_range','opening_hours','ambiance','description','recommended_dishes','menu_link','rating','website','phone_number','is_featured','number_of_rooms','amenities','room_type','activities','duration','age_range','parish','address','perfect_for','curator_note','meal_type','type','kitchen_hours','instagram_url','is_hidden','menus','completed','booking_link','parent_place_id','place_role','brand_name','booking_contact_email','hospitality_group','day_pass_available','day_pass_price','day_pass_includes','day_pass_hours','day_pass_link','day_pass_notes','day_pass_child_price','day_pass_child_age','bookings_email','opening_hours_struct','kitchen_hours_struct','accepts_stay_bookings','booking_mode','booking_contact_name','check_in_time','check_out_time','min_nights','max_guests','cancellation_policy_text','deposit_instructions','deposit_required','deposit_default_amount','deposit_currency','commission_terms','taxes_fees_notes','hold_expiry_minutes','internal_booking_notes','stay_booking_mode','stay_availability_source','stay_availability_url','stay_room_types','stay_min_nights','stay_max_guests','stay_commission_terms','insider_enabled','brand_color'])),'images',to_jsonb(p_images));
end;$$;
-- Only the server may supply verified public photo URLs.
revoke all on function public.admin_studio_apply_place(text,uuid,timestamptz,text[]) from public,anon,authenticated;
grant execute on function public.admin_studio_apply_place(text,uuid,timestamptz,text[]) to service_role;
